  /**
   * <!-- begin-user-doc -->
   * <!-- end-user-doc -->
   * <!-- begin-model-doc -->
   * Summary:
   * Creates a new IPO application for the customer against a target company.
   * The customer must be eligible for IPO, must provide a positive share count and payment amount,
   * and must provide a non-null allowance document.
   * The customer must not already have an approved application for the same company name.
   * Algorithm:
   * 1. Validate inputs:
   *    - company is not null
   *    - shares > 0
   *    - amount > 0
   *    - doc is not null
   * 2. Check isEligibleForIPO(); if false, return false.
   * 3. Check whether there is already an approved application in applications for the same company.name; if yes, return false.
   * 4. Create a new Application with status PENDING and the provided company, shares, amount, and doc.
   * 5. Associate the application with this customer.
   * 6. Add the application to applications.
   * 7. Return true.
   * Related Features:
   * - canApplyForIPO
   * - email
   * - name
   * - surname
   * - telephone
   * - applications
   * - isEligibleForIPO()
   * Related Classes: Application, Company, Document, ApplicationStatus
   * Input:
   * - company : Company
   *   - Target company for the IPO application.
   *   - Must not be null.
   * - shares : int
   *   - Number of shares to apply for.
   *   - Must be greater than 0.
   * - amount : double
   *   - Amount of money to pay.
   *   - Must be greater than 0.
   * - doc : Document
   *   - Legal allowance document.
   *   - Must not be null.
   * Output:
   * - boolean
   * - true if the application is created and stored successfully.
   * - false otherwise.
   * Pre-condition:
   * - Customer instance exists.
   * - Customer has valid identity/contact data for later notifications.
   * - Input parameters satisfy their basic validation rules.
   * - The customer is allowed to start application process only if eligible.
   * Post-condition:
   * - If return value is true:
   *   - a new pending Application is added to applications.
   *   - the new application references the given company, doc, and this customer.
   * - If return value is false:
   *   - applications remain unchanged.
   * <!-- end-model-doc -->
   * @model annotation="http://www.ustb.edu.cn/sei/mde/EnhancedCodeGen generated='true'"
   * @generated NOT
   */
  public boolean createApplication(final Company company, final int shares, final double amount, final Document doc)
  {
    if (company == null || shares <= 0 || amount <= 0 || doc == null)
    {
      return false;
    }

    if (!isEligibleForIPO())
    {
      return false;
    }

    if (applications != null)
    {
      for (Application application : applications)
      {
        if (application != null && application.getStatus() == ApplicationStatus.APPROVAL && application.getCompany() != null
            && company.getName() != null && company.getName().equals(application.getCompany().getName()))
        {
          return false;
        }
      }
    }

    Application application = IpoFactory.eINSTANCE.createApplication();
    application.setStatus(ApplicationStatus.PENDING);
    application.setCompany(company);
    application.setShare(shares);
    application.setAmountOfMoney(amount);
    application.setAllowance(doc);
    application.setCustomer(this);
    getApplications().add(application);
    return true;
  }

